import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.cZsgxozV.js";var i=JSON.parse(`{"title":"Android sideload (Tauri APK)","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/android-sideload.md","filePath":"desktop/android-sideload.md"}`),a={name:`desktop/android-sideload.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="android-sideload-tauri-apk" tabindex="-1">Android sideload (Tauri APK) <a class="header-anchor" href="#android-sideload-tauri-apk" aria-label="Permalink to “Android sideload (Tauri APK)”">​</a></h1><p>DocuHaim Android is a <strong>Tauri v2</strong> shell around the same SPA. It is <strong>not</strong> distributed on Google Play. Install the APK from a dedicated GitHub Release.</p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to “Releases”">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Workflow</th><th>Tag</th><th>Artifacts</th></tr></thead><tbody><tr><td>Desktop</td><td><code>.github/workflows/release-tauri.yml</code></td><td><code>vX.Y.Z</code></td><td>DMG / NSIS</td></tr><tr><td>Android</td><td><code>.github/workflows/release-tauri-android.yml</code></td><td><code>android-vX.Y.Z</code></td><td>APK</td></tr></tbody></table><p>Android and desktop releases are <strong>separate</strong>. Desktop workflow does not upload APKs.</p><h3 id="publish-an-android-build" tabindex="-1">Publish an Android build <a class="header-anchor" href="#publish-an-android-build" aria-label="Permalink to “Publish an Android build”">​</a></h3><ol><li>Actions → <strong>Release Tauri Android</strong> → Run workflow.</li><li>Optional <code>version</code> input (defaults to root <code>package.json</code> version).</li><li>Download the APK from the new <code>android-v…</code> release.</li></ol><h2 id="install-sideload" tabindex="-1">Install (sideload) <a class="header-anchor" href="#install-sideload" aria-label="Permalink to “Install (sideload)”">​</a></h2><ol><li>On the phone, allow install from the browser/Files app (“unknown apps”).</li><li>Open the downloaded <code>.apk</code> and install.</li><li>First launch: unlock with master password and/or <strong>생체 인식</strong> (platform biometric via Stronghold — not browser WebAuthn/PRF).</li></ol><h2 id="features-on-android" tabindex="-1">Features on Android <a class="header-anchor" href="#features-on-android" aria-label="Permalink to “Features on Android”">​</a></h2><ul><li><strong>S3 / WebDAV</strong> — same encrypted credential flow; secrets in Stronghold (app-private).</li><li><strong>Local Haim</strong> — default vault under app data (<code>LocalHaim</code>). You can also pick another folder via the system dialog when available.</li><li><strong><code>.md</code> / <code>.markdown</code> file association</strong> — open markdown from Files / other apps with DocuHaim (vault note if under the Local root, otherwise session workspace).</li><li><strong>Advanced Search</strong> — filename / path / commands only; Lucivy inverted index is disabled.</li><li><strong>share_target</strong> — existing PWA share intake is assumed to keep working; this shell does not reimplement it.</li></ul><h2 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to “Local development”">​</a></h2><p>Requires Android SDK + NDK (<code>NDK_HOME</code> / <code>ANDROID_NDK_HOME</code>), JDK 17, and Rust Android targets.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANDROID_HOME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/Library/Android/sdk   </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># example</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NDK_HOME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ANDROID_HOME/ndk/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:android:init</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">   # once, if gen/android is missing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:android:dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:android:build</span></span></code></pre></div><p>Project files live under <code>src-tauri/gen/android/</code>. Intent filters for markdown are generated from <a href="../../src-tauri/tauri.conf.json"><code>src-tauri/tauri.conf.json</code></a> <code>bundle.fileAssociations</code> on build.</p><h2 id="signing" tabindex="-1">Signing <a class="header-anchor" href="#signing" aria-label="Permalink to “Signing”">​</a></h2><p>Sideload APKs may be debug-signed when release keystore secrets are not configured. For a private release keystore, configure Android signing in the generated Gradle project / CI secrets (not covered by the desktop Apple/Windows signing doc).</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h2><ul><li>Google Play / AAB</li><li>iOS</li><li>Browser WebAuthn PRF in the Android WebView (platform biometric only)</li></ul>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};